static long double swap_sub(long double a, long double b){__asm__("fxch %1\n\tfsub %1, %0" : "+t"(a), "+u"(b));return a*3+b;}static long double add_top(long double a, long double b){__asm__("fadd %%st(1), %%st" : "+t"(a) : "u"(b));return a;}static long double square(long double a){__asm__("fld %%st(0)\n\tfmul %%st(1), %%st\n\tfstp %%st(1)" : "+t"(a));return a;}static long double reversed(long double a, long double b){long double r;__asm__("fsubp %%st, %%st(1)" : "=t"(r) : "0"(a), "u"(b) : "st(1)");return r;}static int below(long double a, long double b){int r;__asm__("fcomi %%st(1), %%st" : "=@ccb"(r) : "t"(a), "u"(b));return r;}static long double square_freed(long double a){__asm__("fld %%st(0)\n\tfmul %%st(1), %%st\n\tfxch\n\tffreep %%st(0)" : "+t"(a));return a;}int tested(int n){long double a=n*0.5L+1,b=n-2.25L;return (int)(swap_sub(a,b)*8)+(int)(add_top(a,b)*4)+(int)square(a)+(int)(square_freed(b)*2)+(int)(reversed(a,b)*16)+below(a,b)*1000+below(b,a)*3000;}